// One node: query OSV, validate, shape. No HTTP Request node.
//
// The three-node version kept returning 200 with a body that had no results in
// it, which the shaping step then read as "no vulnerabilities found". The cause
// was never nailed down, and with a deadline the right move is to delete the
// surface rather than keep guessing at it: doing the fetch here means the
// request body is a JavaScript object this file can see, not an expression
// being re-encoded by a node whose behaviour depends on its settings.

const body = $input.first().json.body || {};
const input = body.input || {};

let pkgs = [];
if (Array.isArray(input.packages)) {
  pkgs = input.packages;
} else if (input.dependencies && typeof input.dependencies === 'object') {
  pkgs = Object.entries(input.dependencies).map(([name, range]) => ({
    name,
    version: String(range).replace(/^[\^~>=<\s]+/, ''),
    ecosystem: input.ecosystem || 'npm',
  }));
} else if (input.name && input.version) {
  // A single package, because this is what an agent sends when a human said
  // "check lodash 4.17.20" and the agent did not feel like building an array.
  pkgs = [{ name: input.name, version: input.version, ecosystem: input.ecosystem || 'npm' }];
}

pkgs = pkgs
  .filter((p) => p && p.name && p.version)
  .map((p) => ({
    name: String(p.name),
    version: String(p.version),
    ecosystem: String(p.ecosystem || input.ecosystem || 'npm'),
  }))
  .slice(0, 50);

if (!pkgs.length) {
  throw new Error('Send {"input":{"packages":[{"name","version","ecosystem"}]}}, {"input":{"dependencies":{...}}}, or {"input":{"name":"lodash","version":"4.17.20"}}');
}

// n8n exposes its own HTTP helper inside the Code node; plain fetch exists on
// modern builds. Try the helper first, because it is the one n8n supports.
async function post(url, payload) {
  if (this && this.helpers && typeof this.helpers.httpRequest === 'function') {
    return await this.helpers.httpRequest({
      method: 'POST',
      url,
      body: payload,
      json: true,
      timeout: 30000,
    });
  }
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const text = await res.text();
  if (!res.ok) throw new Error('OSV answered HTTP ' + res.status + ': ' + text.slice(0, 200));
  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error('OSV did not return JSON: ' + text.slice(0, 200));
  }
}

const queries = pkgs.map((p) => ({
  package: { name: p.name, ecosystem: p.ecosystem },
  version: p.version,
}));

const osv = await post.call(this, 'https://api.osv.dev/v1/querybatch', { queries });

// A scanner that cannot tell "found nothing" from "never asked" is worse than
// no scanner, because it sells a clean bill of health for a question it failed
// to ask. OSV returns one result per query, in order. Anything else means we do
// not know, and the only honest answer is to fail rather than report zero.
const results = osv && osv.results;
if (!Array.isArray(results) || results.length !== pkgs.length) {
  throw new Error(
    'OSV returned ' + (Array.isArray(results) ? results.length : 'no') +
    ' result(s) for ' + pkgs.length + ' query/queries. Refusing to report a clean scan. ' +
    'Response: ' + JSON.stringify(osv).slice(0, 300)
  );
}

const findings = [];
pkgs.forEach((p, i) => {
  const vulns = (results[i] && results[i].vulns) || [];
  if (vulns.length) {
    findings.push({
      package: p.name,
      version: p.version,
      advisories: vulns.map((v) => ({ id: v.id, url: 'https://osv.dev/vulnerability/' + v.id })),
    });
  }
});

// `scanned` and `checkedAt` are part of the product, not decoration: what is
// being bought is a dated statement about a specific set of versions.
return [{ json: { output: {
  scanned: pkgs.length,
  vulnerable: findings.length,
  findings,
  source: 'osv.dev',
  checkedAt: new Date().toISOString(),
} } }];
